// SPDX-License-Identifier: MIT
pragma solidity 0.8.34;

import {ICrossChainProxy} from "../interfaces/ICrossChainProxy.sol";
import {
    CrossChainCall,
    ExpectedOutgoingCrossChainCall,
    ExecutionEntry,
    StaticExecutionEntryL2
} from "../interfaces/IEEZL2.sol";
import {ProxyInfo} from "../interfaces/IEEZ.sol";
import {EEZBase} from "../base/EEZBase.sol";

/// @title EEZL2
/// @notice L2-side contract for cross-chain execution via pre-computed execution tables
/// @dev No rollups, no rollup updates, no ZK proofs. System address loads execution tables,
///      which are consumed sequentially via proxy calls (`executeCrossChainCall`).
/// @dev SELF-RELATIVE directional vocabulary, mirroring L1's directional style: `incomingCalls`
///      holds the cross-chain calls executed ON this L2 on behalf of remote callers (the
///      counterparty may be L1 OR another L2), and `expectedOutgoingCalls` holds the pre-computed
///      results of reentrant calls fired FROM this L2 during execution. See `IEEZL2.sol`.
/// @dev Mirrors `EEZ` (L1) structurally minus the L1-only machinery — no rollup updates / ether
///      accounting, no rollup registry, no proofs, no per-rollup queues, no proxy-protection set.
///      Each frame carries its OWN flat call array (`_processIncomingCalls` walks it by a local index, no
///      global cursor); the reentrant (outgoing) table is a single unified `expectedOutgoingCalls`,
///      content-addressed by `expectedOutgoingHash` and forward-scanned by `_lastOutgoingCallConsumed`.
contract EEZL2 is EEZBase {
    // ──────────────────────────────────────────────
    //  Immutables
    // ──────────────────────────────────────────────

    /// @notice The rollup ID this L2 belongs to
    uint64 public immutable ROLLUP_ID;

    /// @notice The system address authorized for admin operations (load/replace execution table).
    /// @dev TRUST ASSUMPTION: node-controlled system address with no private key — never adversarial
    ///      and not reentry-reachable, so table loads/replacements are trusted (no attacker can wipe
    ///      or swap the table mid-execution).
    address public immutable SYSTEM_ADDRESS;

    /// @notice Recipient of ether swept from proxies at construction, independent of system funding.
    address public immutable RECOVERY_ADDRESS;

    /// @notice Whether the `callGas` folded into outgoing call hashes is the observed `gasleft()`.
    /// @dev When false, `callGas` is fixed at 0 — outgoing hashes are then gas-independent and can
    ///      be pre-computed without observing the forwarded gas. Gas-observed keying (`true`) is the
    ///      intended production mode once the node supplies observed gas.
    bool public immutable USE_GAS_LEFT;

    // ──────────────────────────────────────────────
    //  Storage
    // ──────────────────────────────────────────────

    /// @notice Reusable execution slots; only indices below entriesLength belong to the current table.
    /// @dev Getters can expose retained inactive rows. Consumers must respect the active length.
    mapping(uint256 => ExecutionEntry) public entries;

    /// @notice Reusable static slots; only indices below staticEntriesLength are active in the load block.
    mapping(uint256 => StaticExecutionEntryL2) public staticEntries;

    /// @notice Last block number when execution table was loaded
    uint256 public lastLoadBlock;

    /// @notice Index of the next execution entry to consume
    uint256 public entryIndex;

    /// @notice Number of active execution entries, including already-consumed rows.
    uint256 public entriesLength;

    /// @notice Number of active top-level static entries.
    uint256 public staticEntriesLength;

    // ──────────────────────────────────────────────
    //  Transient execution state
    // ──────────────────────────────────────────────

    /// @notice True while inside a cross-chain call execution. Set at `_executeEntry` start, cleared
    ///         at its end; a revert rolls it back. Backs `_insideExecution()` (L1 derives the same
    ///         predicate from its proxy-protection array, which L2 doesn't have).
    bool transient _executing;

    /// @notice Forward-scan position into the entry's unified `expectedOutgoingCalls`. MUST be
    ///         transient — `_consumeNestedCall` / `staticCrossChainCall` read it from fresh reentrant
    ///         frames; it rides the `ContextResult` payload across a revert-span boundary.
    uint256 transient _lastOutgoingCallConsumed;

    // ──────────────────────────────────────────────
    //  Events
    // ──────────────────────────────────────────────

    /// @notice Emitted with the loaded execution and static entries after replacing both tables
    ///         and resetting entryIndex to zero.
    event ExecutionTableLoaded(ExecutionEntry[] entries, StaticExecutionEntryL2[] staticEntries);

    /// @notice Emitted when an execution entry is consumed
    event ExecutionConsumed(bytes32 indexed crossChainCallHash, uint256 indexed entryIndex);

    /// @notice Emitted when the system address initiates an incoming cross-chain call from another
    ///         rollup. Field order mirrors `computeCrossChainCallHash`; all fields are the inbound
    ///         call's own (`incomingCalls[0]`), folded into its hash.
    event IncomingCrossChainCallExecuted(
        bytes32 indexed crossChainCallHash,
        bool isStatic,
        address sourceAddress,
        uint64 sourceRollup,
        address destination,
        uint256 value,
        uint64 callGas,
        bytes data
    );

    /// @notice Emitted when a cross-chain call LEAVING this L2 is executed via proxy. `callGas` is
    ///         the value folded into the hash: with `USE_GAS_LEFT`, the gas left when the hash is
    ///         computed (after proxy validation, the block check and any system-address transfer); else 0.
    /// @dev Overloads `EEZBase.CrossChainCallExecuted` (L1's five-field form) with an extra
    ///      trailing `callGas`; the two signatures have different topic0s.
    event CrossChainCallExecuted(
        bytes32 indexed crossChainCallHash,
        address indexed proxy,
        address sourceAddress,
        bytes callData,
        uint256 value,
        uint64 callGas
    );

    /// @notice Emitted after each call completes in `_processIncomingCalls`.
    /// @dev Logs inside a revertNextNCalls span are discarded, since that context will be reverted.
    ///      Call numbers are local to each frame's array and restart in nested frames.
    event CallResult(uint256 indexed entryIndex, uint256 indexed callNumber, bool success, bytes returnData);

    /// @notice Emitted after entry checks
    event EntryExecuted(
        uint256 indexed entryIndex, bytes32 rollingHash, uint256 callsProcessed, uint256 outgoingCallsConsumed
    );

    /// @notice Emitted after a `revertNextNCalls` span: `nCalls` calls ran via `executeInContextAndRevert`
    ///         (each succeeding or failing on its own), then their state effects were rolled back.
    event CallsReverted(uint256 indexed entryIndex, uint256 startCallNumber, uint256 nCalls);

    // ──────────────────────────────────────────────
    //  Errors
    // ──────────────────────────────────────────────

    /// @notice Error when caller is not the system address
    error Unauthorized();

    /// @notice Error when constructor is given the reserved mainnet rollup id (0)
    error InvalidRollupId();

    /// @notice The proxy recovery recipient must be nonzero, as on L1.
    error InvalidRecoveryAddress();

    /// @notice Error when execution is attempted in a different block than the last load
    error ExecutionNotInCurrentBlock();

    /// @notice Error when ETH transfer to system address fails
    error EtherTransferFailed();

    /// @notice Error when `executeIncomingCrossChainCall` is called with no entries
    error EmptyEntries();

    /// @notice Entry 0 has no incoming calls — `incomingCalls[0]` must be the inbound call
    error EmptyIncomingCalls();

    /// @notice Entry 0's `proxyEntryHash` doesn't match the hash of its own `incomingCalls[0]`
    error EntryHashMismatch();

    /// @notice No entry matched an outgoing call: a top-level mutable miss, or a static miss in
    ///         either branch. Carries the computed L2-outgoing hash and the observed `callGas` so
    ///         the entry-builder can reproduce the key.
    /// @dev Observability aid: unlike L1's bare `ExecutionNotFound`, the payload exposes the key
    ///      the manager searched for, which under `USE_GAS_LEFT` is difficult to be computed off-chain.
    error EntryNotFound(bytes32 crossChainCallHash, uint64 callGas);

    /// @notice A `revertNextNCalls` span declares more calls than remain in its array (malformed entry).
    error RevertSpanOutOfBounds(uint256 start, uint256 span, uint256 length);

    // ──────────────────────────────────────────────
    //  Constructor
    // ──────────────────────────────────────────────

    /// @notice Configures this L2's identity, privileged system caller, and outgoing call gas hashing.
    /// @param _rollupId Non-zero; 0 is reserved as the mainnet sentinel in call hashes.
    /// @param _systemAddress The privileged address allowed to load execution tables
    /// @param _useGasLeft Whether outgoing call hashes fold the observed `gasleft()` (true) or a
    ///        fixed 0 (false — gas-independent keying)
    /// @param _recoveryAddress Nonzero recipient of ether swept from proxies at construction
    constructor(uint64 _rollupId, address _systemAddress, bool _useGasLeft, address _recoveryAddress) {
        if (_rollupId == 0) revert InvalidRollupId();
        if (_recoveryAddress == address(0)) revert InvalidRecoveryAddress();
        RECOVERY_ADDRESS = _recoveryAddress;
        ROLLUP_ID = _rollupId;
        SYSTEM_ADDRESS = _systemAddress;
        USE_GAS_LEFT = _useGasLeft;
    }

    // ──────────────────────────────────────────────
    //  Modifiers
    // ──────────────────────────────────────────────

    /// @dev Restricts execution to the configured SYSTEM_ADDRESS; other callers revert Unauthorized.
    modifier onlySystemAddress() {
        if (msg.sender != SYSTEM_ADDRESS) revert Unauthorized();
        _;
    }

    // ──────────────────────────────────────────────
    //  Admin: load execution table
    // ──────────────────────────────────────────────

    /// @notice Loads execution entries and static entries into the execution table (system only)
    /// @dev Replaces active bounds and overwrites slots without deleting the old table.
    ///      Retained inactive slots are never searched. Entries must be consumed in the same block.
    ///      Payable: msg.value adds pooled system funding. Table replacement retains unused ETH;
    ///      no per-table ledger or per-load conservation check exists. The node/circuit must
    ///      reconcile inventory across partial consumption, replacement and reverted transfers.
    /// @param _entries The execution entries to load
    /// @param _staticEntries The top-level static entries to load
    function loadExecutionTable(
        ExecutionEntry[] calldata _entries,
        StaticExecutionEntryL2[] calldata _staticEntries
    )
        external
        payable
        onlySystemAddress
    {
        _loadExecutionTable(_entries, _staticEntries);
    }

    /// @notice Internal: replaces the execution table and resets the consumption cursor
    /// @dev Shared between `loadExecutionTable` and `executeIncomingCrossChainCall`.
    ///      Reset cost is independent of the old table size. Overwriting a row may still clear
    ///      shortened nested arrays/bytes. A reverting delivery restores rows, bounds and cursor.
    /// @param _entries Replacement execution entries in consumption order.
    /// @param _staticEntries Replacement pool of static entries pinned to execution cursors.
    function _loadExecutionTable(
        ExecutionEntry[] calldata _entries,
        StaticExecutionEntryL2[] calldata _staticEntries
    )
        internal
    {
        entryIndex = 0;
        entriesLength = _entries.length;
        staticEntriesLength = _staticEntries.length;

        for (uint256 i = 0; i < _entries.length; i++) {
            entries[i] = _entries[i];
        }
        for (uint256 i = 0; i < _staticEntries.length; i++) {
            staticEntries[i] = _staticEntries[i];
        }
        lastLoadBlock = block.number;
        emit ExecutionTableLoaded(_entries, _staticEntries);
    }

    // ──────────────────────────────────────────────
    //  Execution entry points
    // ──────────────────────────────────────────────

    /// @notice Executes a cross-chain call initiated by an authorized proxy
    /// @param sourceAddress The original caller address (msg.sender as seen by the proxy)
    /// @param callData The original calldata sent to the proxy
    /// @return result The return data from the execution
    function executeCrossChainCall(
        address sourceAddress,
        bytes calldata callData
    )
        external
        payable
        returns (bytes memory result)
    {
        (address destAddress, uint64 destRid) = _validateProxyAndGetDestinationInfo();

        // burn ether — return to system address
        if (msg.value > 0) {
            (bool success,) = SYSTEM_ADDRESS.call{value: msg.value}("");
            if (!success) revert EtherTransferFailed();
        }

        // Intentionally sample remaining gas here, after proxy/storage checks and any value
        // transfer. This is not gas at proxy or manager entry; replay must reproduce this point.
        uint64 callGas = USE_GAS_LEFT ? uint64(gasleft()) : 0;
        bytes32 crossChainCallHash = computeCrossChainCallHash(
            NOT_STATIC_CALL, sourceAddress, ROLLUP_ID, destAddress, destRid, msg.value, callGas, callData
        );
        emit CrossChainCallExecuted(crossChainCallHash, msg.sender, sourceAddress, callData, msg.value, callGas);

        if (_insideExecution()) {
            // Reentrant — resolve against the active entry's unified outgoing table
            return _consumeNestedCall(crossChainCallHash);
        }

        return _consumeAndExecute(crossChainCallHash, callGas);
    }

    /// @notice System-initiated execution of an incoming cross-chain call from another rollup
    /// @dev Atomically replaces the execution table and drives `entries[0]`; reentrant calls
    ///      consume from its `expectedOutgoingCalls`. `incomingCalls[0]` IS the inbound call —
    ///      its hash must equal `entries[0].proxyEntryHash` (checked on-chain); that it matches
    ///      what actually arrived is a prover constraint. msg.value adds pooled system funding;
    ///      node/circuit accounting must reconcile partial consumption and retained inventory
    ///      across loads (no per-table balance check). `entries[0]` stays fully general:
    ///      `success == false` reverts the whole delivery, and `revertNextNCalls` on the inbound
    ///      call rolls back its destination effects while the delivery commits.
    /// @param _entries The execution entries to load (entries[0] is consumed by this call)
    /// @param _staticEntries The static entries to load (used for STATICCALL reads)
    /// @return result The pre-computed return data from `entries[0]`
    function executeIncomingCrossChainCall(
        ExecutionEntry[] calldata _entries,
        StaticExecutionEntryL2[] calldata _staticEntries
    )
        external
        payable
        onlySystemAddress
        returns (bytes memory result)
    {
        if (_entries.length == 0) revert EmptyEntries();
        if (_entries[0].incomingCalls.length == 0) revert EmptyIncomingCalls();

        // 1. Replace the execution table (same logic as loadExecutionTable)
        _loadExecutionTable(_entries, _staticEntries);

        // 2. Bind the entry's identity to its own inbound call: `proxyEntryHash` must be the
        //    hash of `incomingCalls[0]` (mirrors L1 `_consumeAndExecuteEntry`'s hash match).
        CrossChainCall calldata inbound = _entries[0].incomingCalls[0];
        bytes32 crossChainCallHash = computeCrossChainCallHash(
            inbound.isStatic,
            inbound.sourceAddress,
            inbound.sourceRollupId,
            inbound.targetAddress,
            ROLLUP_ID,
            inbound.value,
            inbound.gas,
            inbound.data
        );
        ExecutionEntry storage entry = entries[0];
        if (entry.proxyEntryHash != crossChainCallHash) revert EntryHashMismatch();

        emit IncomingCrossChainCallExecuted(
            crossChainCallHash,
            inbound.isStatic,
            inbound.sourceAddress,
            inbound.sourceRollupId,
            inbound.targetAddress,
            inbound.value,
            inbound.gas,
            inbound.data
        );

        // Same consumption signal the proxy-driven path emits, so a log reader sees every entry
        // that ran regardless of which entry point drove it.
        emit ExecutionConsumed(crossChainCallHash, 0);

        // 3. Execute. `_currentEntryIndex`, `_rollingHash`, `_lastOutgoingCallConsumed`,
        //    `_executing` are all `transient` and default to zero/false at the start of every tx;
        //    SYSTEM_ADDRESS invokes this as a top-level call, once per tx, so they're already what
        //    `_executeEntry` expects (entry index 0, fresh rolling hash, cursor at 0, not executing).
        _currentEntryIndex = 0;
        _executeEntry(entry);

        // 4. Advance past entries[0] so follow-up `executeCrossChainCall`s don't re-consume it.
        //    SYSTEM_ADDRESS is not reentry-reachable so no `_insideExecution()` guard is needed.
        entryIndex = 1;

        return entry.returnData;
    }

    // ──────────────────────────────────────────────
    //  Internal execution
    // ──────────────────────────────────────────────

    /// @notice The unified reentrant (outgoing) table a proxy re-entry resolves against — always the
    ///         entry currently in `_executeEntry`. L2 has a single `entries` table, so the
    ///         transient `_currentEntryIndex` indexes it directly. A reverted sub-execution shares the
    ///         same table for its own reentrant calls, disambiguated by the `_rollingHash` folded into
    ///         each `expectedOutgoingHash`.
    /// @return Storage reference to the current entry's expected outgoing-call table.
    function _getExpectedOutgoingCalls() internal view returns (ExpectedOutgoingCrossChainCall[] storage) {
        return entries[_currentEntryIndex].expectedOutgoingCalls;
    }

    /// @notice Resolves a reentrant (outgoing) CALL: a plain-success entry consumed from
    ///         `expectedOutgoingCalls`, or a reverted entry run as a sub-execution.
    /// @dev Entries are content-addressed by `expectedOutgoingHash == keccak256(crossChainCallHash, _rollingHash)`,
    ///      where `_rollingHash` folds every prior call and nesting boundary, so it uniquely pins the
    ///      execution point. The scan walks STRICT FORWARD from `_lastOutgoingCallConsumed`; the first
    ///      match IS the entry, and its `success` flag selects the path in `_resolveNestedReentrant`
    ///      (commit vs run-and-revert). Static entries can't match here — their `crossChainCallHash`
    ///      folds `isStatic = true`, while this match is keyed with `isStatic = false`; the proxy
    ///      routes reentrant STATICCALLs to `staticCrossChainCall`. On no match, `_rollingHashCallNotFound`
    ///      folds CALL_NOT_FOUND so the entry reverts at its rolling-hash check (`RollingHashMismatch`).
    /// @param crossChainCallHash Outgoing call identity to bind to the current rolling hash for lookup.
    /// @return Matched successful call's return data, or empty bytes after marking a missing call.
    function _consumeNestedCall(bytes32 crossChainCallHash) internal returns (bytes memory) {
        ExpectedOutgoingCrossChainCall[] storage expectedCalls = _getExpectedOutgoingCalls();
        bytes32 expectedOutgoingHash = _computeExpectedL1toL2Hash(crossChainCallHash, _rollingHash);

        for (uint256 i = _lastOutgoingCallConsumed; i < expectedCalls.length; i++) {
            if (expectedCalls[i].expectedOutgoingHash == expectedOutgoingHash) {
                // Advance the cursor PAST this match before resolving it
                _lastOutgoingCallConsumed = i + 1;
                return _resolveNestedReentrant(expectedCalls[i], crossChainCallHash);
            }
        }

        // No match: CALL_NOT_FOUND is a distinct tag from the CALL_END(true, "") folded for a normal
        // empty return, so it can't be forged as one. The hash divergence is what the entry boundary
        // checks. ContextResult carries it across deliberate revert spans; an ordinary
        // enclosing revert rolls back the marker with the rest of that frame.
        _rollingHashCallNotFound(crossChainCallHash);
        return "";
    }

    /// @notice Resolves a matched reentrant (outgoing) CALL by running its OWN `incomingCalls[]` sub-array.
    /// @dev Takes the matched entry by `storage` pointer (the caller already resolved + indexed it, and
    ///      advanced `_lastOutgoingCallConsumed` past it). SUCCESS commits the sub-execution into the
    ///      host's continuous `_rollingHash` (NESTED_END) and returns `returnData`. REVERTED checks the
    ///      sub-hash against `revertedOrStaticRollingHash` and reverts with `returnData`; the terminal
    ///      revert rolls back the frame's state, hash, and cursor (no save needed).
    /// @param expectedOutgoing Matched row containing incoming sub-calls, the expected outcome, and cached result.
    /// @param crossChainCallHash Outgoing call identity folded into the nested-frame opening hash.
    /// @return Cached return data when the matched call succeeds; a matched failure reverts with its cached data.
    function _resolveNestedReentrant(
        ExpectedOutgoingCrossChainCall storage expectedOutgoing,
        bytes32 crossChainCallHash
    )
        internal
        returns (bytes memory)
    {
        CrossChainCall[] memory incomingCalls = expectedOutgoing.incomingCalls;

        // Open the frame and run the sub-array (cursor already advanced by the caller, so the sub-frame's
        // own reentrant calls scan strictly forward).
        _rollingHashNestedBegin(crossChainCallHash);
        _processIncomingCalls(incomingCalls);

        if (expectedOutgoing.success) {
            // Defensive check of the prover constraint: the field is unused when success.
            if (expectedOutgoing.revertedOrStaticRollingHash != bytes32(0)) {
                revert SuccessRowWithRevertedOrStaticHash();
            }
            // Updates the rolling hash closing the nested call
            _rollingHashNestedEnd();
            return expectedOutgoing.returnData;
        } else {
            // It reverts with the expected saved revert data only if the expected rolling hash matches
            if (_rollingHash != expectedOutgoing.revertedOrStaticRollingHash) revert RollingHashMismatch();
            bytes memory returnData = expectedOutgoing.returnData;
            assembly {
                revert(add(returnData, 0x20), mload(returnData))
            }
        }
    }

    /// @notice Consumes the next execution entry (forward-scanning for the matching `proxyEntryHash`),
    ///         runs it, and verifies the rolling hash.
    /// @dev Forward-scan from the cursor skips intervening non-matches so a top-level call can reach
    ///      past failed entries only when their hashes do not match the new call. A matching
    ///      failed entry is retried because its revert restores the cursor.
    ///      Reverting calls are normal entries (`success == false`); the static pool is read-only.
    /// @param crossChainCallHash The expected action input hash for the next entry
    /// @param callGas Outgoing call's gas-hash field, included in EntryNotFound if lookup fails.
    /// @return result The pre-computed return data from the action
    function _consumeAndExecute(bytes32 crossChainCallHash, uint64 callGas) internal returns (bytes memory result) {
        uint256 idx = _findMatchingEntry(entryIndex, crossChainCallHash, callGas);
        entryIndex = idx + 1;
        ExecutionEntry storage entry = entries[idx];

        emit ExecutionConsumed(crossChainCallHash, idx);

        _currentEntryIndex = idx;
        _executeEntry(entry);

        // Reset the entry pointer now the entry is done (hygiene/symmetry — it's only read
        // mid-`_executeEntry` and always re-set before the next read). On a revert it rolls back to 0.
        _currentEntryIndex = 0;

        return entry.returnData;
    }

    /// @notice Forward-scans `entries` from `startIndex` for the FIRST entry whose `proxyEntryHash`
    ///         matches `crossChainCallHash`, returning its index. Reverts `EntryNotFound` if the
    ///         scan reaches the end with no match.
    /// @param startIndex Inclusive first index to inspect in entries.
    /// @param crossChainCallHash Required proxy-entry hash.
    /// @param callGas Outgoing call's gas-hash field, included in EntryNotFound if lookup fails.
    /// @return Index of the first matching entry; reverts if no candidate matches.
    function _findMatchingEntry(
        uint256 startIndex,
        bytes32 crossChainCallHash,
        uint64 callGas
    )
        internal
        view
        returns (uint256)
    {
        uint256 queueLen = entriesLength;
        for (uint256 i = startIndex; i < queueLen; i++) {
            if (entries[i].proxyEntryHash == crossChainCallHash) return i;
        }
        revert EntryNotFound(crossChainCallHash, callGas);
    }

    /// @notice Seeds the rolling hash, processes the entry's direct calls, verifies the rolling
    ///         hash, and (when `!success`) reverts with the entry's `returnData`.
    /// @dev `entry.incomingCalls` is only the calls it runs directly (each reentrant frame carries its own
    ///      sub-calls); `_processIncomingCalls` runs the whole array, with early return on gas shortage .
    ///      `_executing` is set true for the whole span (backs `_insideExecution()`) so a reentrant call routes through `_consumeNestedCall`.
    ///      Proxy re-entries resolve the reentrant table from storage via `_getExpectedOutgoingCalls()`.
    /// @param entry Stored execution entry whose calls, rolling hash, and expected outcome are processed.
    function _executeEntry(ExecutionEntry storage entry) internal {
        // Flips `_insideExecution()` true; cleared on the success path, rolled back on a revert.
        _executing = true;

        _seedRollingHash(entry.proxyEntryHash); // initial hash: binds the entry identity
        _lastOutgoingCallConsumed = 0;

        // Storage→memory copy of the entry's calls (mirrors L1's by-`memory` processing).
        _processIncomingCalls(entry.incomingCalls);

        // A reentrant no-match folded CALL_NOT_FOUND into the rolling hash, so it surfaces here as a
        // `RollingHashMismatch` — no separate no-match check needed. No reentrant table-length check:
        // the unified `expectedOutgoingCalls` mixes plain-success entries with static / reverted ones
        // (content-addressed, may be unused); completeness of the success entries is enforced by the
        // rolling hash, and an unused entry is inert.
        if (_rollingHash != entry.rollingHash) revert RollingHashMismatch();

        emit EntryExecuted(_currentEntryIndex, _rollingHash, entry.incomingCalls.length, _lastOutgoingCallConsumed);

        // Top-level reverting entry: the trace is now verified, so unwind everything — the inbound
        // value, the cursor advance, and these cleanups all roll back with the revert, surfacing
        // `returnData` to the caller. Mirrors `_resolveNestedReentrant`'s `!success` branch.
        if (!entry.success) {
            bytes memory returnData = entry.returnData;
            assembly {
                revert(add(returnData, 0x20), mload(returnData))
            }
        }

        _executing = false; // resets _insideExecution() to false
        _rollingHash = bytes32(0); // reset so the next entry's `_seedRollingHash` zero-guard passes
    }

    /// @notice Initializes `_rollingHash` to the entry's BEGIN seed — binds the entry's identity
    ///         (`proxyEntryHash` == its crossChainCallHash) so nested frames inherit it transitively.
    /// @dev Mirrors L1's `_rollingHashEntryBegin` with an empty rollup-update prefix (L2 has no rollup
    ///      updates), keeping the cross-chain hashing scheme identical modulo the dropped updates:
    ///        _rollingHash = keccak(bytes32(0), proxyEntryHash)
    /// @param proxyEntryHash Entry identity used to seed the initially empty rolling hash.
    function _seedRollingHash(bytes32 proxyEntryHash) internal {
        if (_rollingHash != bytes32(0)) revert RollingHashNotCleared();
        _rollingHash = keccak256(abi.encodePacked(bytes32(0), proxyEntryHash));
    }

    /// @notice Runs `calls` in an isolated context that always reverts (force-revert span executor).
    ///         Receives the span slice by `memory` (ABI-encoded across the self-call) since a
    ///         `storage` ref can't cross an external boundary; walks the slice, possibly stopping on gas shortage.
    /// @param calls Call span to execute before reverting with the resulting hash and outgoing-call cursor.
    function executeInContextAndRevert(CrossChainCall[] memory calls) external {
        if (msg.sender != address(this)) revert NotSelf();
        _processIncomingCalls(calls);
        revert ContextResult(_rollingHash, _lastOutgoingCallConsumed);
    }

    /// @notice Walks the `calls` array until completion or gas shortage (the calls an entry runs directly, a reentrant frame's
    ///         own calls, or a force-revert span slice), walked by a plain LOCAL index, folding the
    ///         rolling hash.
    /// @dev The index is a local, not transient: it auto-survives a reentrant proxy call (the outer
    ///      stack is preserved across the return), so there's nothing to save/restore for the
    ///      incoming-call position. L2 has no ether accounting (unlike L1), so this returns nothing.
    /// @param calls Ordered incoming calls for this entry, nested frame, or force-revert span.
    function _processIncomingCalls(CrossChainCall[] memory calls) internal {
        for (uint256 i = 0; i < calls.length;) {
            // Reject this manager as a destination to prevent re-entry with an authorized proxy's identity.
            _validateCallDestination(calls[i].targetAddress);

            uint256 revertNextNCalls = calls[i].revertNextNCalls;

            if (revertNextNCalls == 0) {
                CrossChainCall memory cc = calls[i];

                // Fold the call's identity (target on this L2 = ROLLUP_ID, source = its rollup) into CALL_BEGIN.
                _rollingHashCallBegin(
                    computeCrossChainCallHash(
                        cc.isStatic,
                        cc.sourceAddress,
                        cc.sourceRollupId,
                        cc.targetAddress,
                        ROLLUP_ID,
                        cc.value,
                        ZERO_CALL_GAS,
                        cc.data
                    )
                );

                address sourceProxy = getOrCreateCrossChainProxy(cc.sourceAddress, cc.sourceRollupId);

                bytes memory payload =
                    abi.encodeCall(ICrossChainProxy.executeOnBehalf, (cc.targetAddress, cc.gas, cc.data));

                // Check if the context has enough gas.
                if (!_hasEnoughCallGas(cc.gas, payload.length, cc.value)) {
                    _rollingHashCallInsufficientGas();
                    return;
                }

                bool success;
                bytes memory retData;
                if (cc.isStatic) {
                    // Read-only dispatch: STATICCALL carries no value and reverts on any state write.
                    // A static call loaded with value is malformed — reject it rather than drop the value.
                    if (cc.value != 0) revert StaticCallWithValue();
                    (success, retData) = sourceProxy.staticcall(payload);
                } else {
                    (success, retData) = sourceProxy.call{value: cc.value}(payload);
                }

                _rollingHashCallEnd(success, retData);
                emit CallResult(_currentEntryIndex, i, success, retData);
                i++;
            } else {
                // Force-revert span: the next `n` calls (this one included) run with their actual outcomes, then have
                // their state rolled back. Run them in an isolated self-call that always reverts; its
                // committed-to-`_rollingHash` and reentrant-consumption escape via `ContextResult` and
                // are restored here, while the EVM discards the state. A no-match inside the span is
                // already folded into that `_rollingHash`, so it rides out with no separate flag.
                if (i + revertNextNCalls > calls.length) {
                    revert RevertSpanOutOfBounds(i, revertNextNCalls, calls.length);
                }
                // Zero the trigger's span marker in our throwaway memory copy (the slice copies it),
                // so the isolated re-run reads it as a normal call instead of recursing into the span.
                calls[i].revertNextNCalls = 0;

                CrossChainCall[] memory revertedSpan = _sliceCrossChainCalls(calls, i, revertNextNCalls);
                try this.executeInContextAndRevert(revertedSpan) {}
                catch (bytes memory revertData) {
                    (_rollingHash, _lastOutgoingCallConsumed) = _decodeContextResult(revertData);
                }
                emit CallsReverted(_currentEntryIndex, i, revertNextNCalls);
                i += revertNextNCalls; // skip past the span — its calls ran inside the self-call
            }
        }
    }

    // ──────────────────────────────────────────────
    //  Static entries
    // ──────────────────────────────────────────────

    /// @notice Resolves a pre-computed static entry.
    /// @dev Inside an execution: scans the active entry's unified `expectedOutgoingCalls` for an entry
    ///      whose `expectedOutgoingHash` matches `keccak256(crossChainCallHash, _rollingHash)` — the
    ///      same content-addressed key the reentrant CALLs use. The `crossChainCallHash` here folds
    ///      `isStatic = true`, so only static entries can match. Outside: scans the `staticEntries`
    ///      pool for a matching `crossChainCallHash` and live `entryIndex`, gated on
    ///      `lastLoadBlock == block.number`. tload works in static context, so
    ///      the transient tracking variables are readable.
    /// @param sourceAddress The original caller address (msg.sender as seen by the proxy)
    /// @param callData The original calldata sent to the proxy
    /// @return The pre-computed return data
    function staticCrossChainCall(address sourceAddress, bytes calldata callData) external view returns (bytes memory) {
        (address destAddress, uint64 destRid) = _validateProxyAndGetDestinationInfo();

        // Static outgoing calls use the same gas-keying policy as mutable outgoing calls.
        // Sample after proxy validation/storage reads, before lookup; no value transfer applies.
        uint64 callGas = USE_GAS_LEFT ? uint64(gasleft()) : 0;
        bytes32 crossChainCallHash = computeCrossChainCallHash(
            IS_STATIC,
            sourceAddress,
            ROLLUP_ID,
            destAddress,
            destRid,
            0, // value is always 0 in static context
            callGas,
            callData
        );

        // Nested: the active entry's unified reentrant table, content-addressed by `expectedOutgoingHash`.
        // `crossChainCallHash` was computed with `isStatic = true`, so it can only match a static entry.
        // A STATICCALL cannot mutate the cursor, so a static read is position-pinned by the rolling hash
        // rather than consumed.
        if (_insideExecution()) {
            bytes32 expectedOutgoingHash = _computeExpectedL1toL2Hash(crossChainCallHash, _rollingHash);
            // Forward scan from the cursor — same strict-forward window as `_consumeNestedCall`
            // (a static read cannot advance the cursor, but it still only matches at/after it).
            ExpectedOutgoingCrossChainCall[] storage expectedCalls = _getExpectedOutgoingCalls();
            for (uint256 i = _lastOutgoingCallConsumed; i < expectedCalls.length; i++) {
                ExpectedOutgoingCrossChainCall storage expectedCall = expectedCalls[i];
                if (expectedCall.expectedOutgoingHash == expectedOutgoingHash) {
                    if (_resolveStaticEntry(
                            expectedCall.incomingCalls,
                            expectedCall.revertedOrStaticRollingHash,
                            expectedCall.success,
                            expectedCall.returnData
                        )) {
                        return expectedCall.returnData;
                    }
                }
            }
            revert EntryNotFound(crossChainCallHash, callGas);
        }

        // Top-level: same-block pool, matched by hash and the current  entry cursor.
        for (uint256 i = 0; i < staticEntriesLength; i++) {
            StaticExecutionEntryL2 storage staticEntry = staticEntries[i];
            if (staticEntry.proxyEntryHash == crossChainCallHash && staticEntry.expectedEntryIndex == entryIndex) {
                if (_resolveStaticEntry(
                        staticEntry.incomingCalls, staticEntry.rollingHash, staticEntry.success, staticEntry.returnData
                    )) {
                    return staticEntry.returnData;
                }
            }
        }

        revert EntryNotFound(crossChainCallHash, callGas);
    }

    /// @notice Returns false on a callback-hash mismatch so lookup can try the next candidate.
    ///         Empty sub-call arrays hash to zero and are also checked. A matching failed
    ///         entry reverts with its cached data; a matching successful entry returns true.
    /// @param calls Stored read-only sub-calls to replay for this candidate.
    /// @param revertedOrStaticRollingHash Expected accumulator of the sub-call outcomes.
    /// @param success Whether a matching candidate should return successfully or revert.
    /// @param returnData Cached revert payload used when the hash matches and success is false.
    /// @return True for a matching successful candidate, false for a hash mismatch; a matching failure reverts.
    function _resolveStaticEntry(
        CrossChainCall[] storage calls,
        bytes32 revertedOrStaticRollingHash,
        bool success,
        bytes memory returnData
    )
        internal
        view
        returns (bool)
    {
        if (_processStaticIncomingCalls(calls) != revertedOrStaticRollingHash) {
            return false;
        }

        if (!success) {
            assembly {
                revert(add(returnData, 0x20), mload(returnData))
            }
        }
        return true;
    }

    /// @notice Runs the static entry's `calls[]` in static context, folding an untagged rolling hash verified
    ///         against `StaticExecutionEntryL2.rollingHash` / `ExpectedOutgoingCrossChainCall.revertedOrStaticRollingHash`.
    /// @dev No `revertNextNCalls` handling — there is no state to roll back (== 0 is a prover
    ///      constraint); referenced proxies must already be deployed (CREATE2 is unavailable
    ///      inside a STATICCALL frame).
    /// @param calls Ordered read-only calls, each with zero value and no force-revert span.
    /// @return computedHash Accumulated sub-call outcomes, or zero when calls is empty.
    function _processStaticIncomingCalls(CrossChainCall[] memory calls) internal view returns (bytes32 computedHash) {
        for (uint256 i = 0; i < calls.length; i++) {
            CrossChainCall memory cc = calls[i];

            // Reject this manager as a destination to prevent re-entry with an authorized proxy's identity.
            _validateCallDestination(cc.targetAddress);

            // Dispatch is read-only unconditionally, so the declared flag and value must agree,
            // and a revert span is meaningless (nothing to roll back).
            if (!cc.isStatic) revert NonStaticSubCall();
            if (cc.value != 0) revert StaticCallWithValue();
            if (cc.revertNextNCalls != 0) revert StaticCallWithRevertSpan();

            address sourceProxy = computeCrossChainProxyAddress(cc.sourceAddress, cc.sourceRollupId);
            // STATICCALL to a codeless address silently succeeds — reject so the prover can't pre-hash a no-op.
            if (sourceProxy.code.length == 0) revert StaticCallProxyNotDeployed(sourceProxy);
            bytes memory payload = abi.encodeCall(ICrossChainProxy.executeOnBehalf, (cc.targetAddress, cc.gas, cc.data));

            // Check if the context has enough gas.
            if (!_hasEnoughCallGas(cc.gas, payload.length, 0)) revert InsufficientCallGas(cc.gas);

            (bool success, bytes memory retData) = sourceProxy.staticcall(payload);

            computedHash = _rollingHashStaticResult(computedHash, success, retData);
        }
    }

    // ──────────────────────────────────────────────
    //  Internal helpers
    // ──────────────────────────────────────────────

    /// @notice Validates the calling proxy and current-block table load, then returns its destination address and rollup.
    /// @return Remote destination address represented by the calling proxy.
    /// @return Remote rollup ID represented by the calling proxy.
    function _validateProxyAndGetDestinationInfo() internal view returns (address, uint64) {
        ProxyInfo storage proxyInfo = authorizedProxies[msg.sender];
        if (!proxyInfo.isProxy) revert UnauthorizedProxy();
        if (lastLoadBlock != block.number) revert ExecutionNotInCurrentBlock();
        return (proxyInfo.originalAddress, proxyInfo.originalRollupId);
    }

    /// @notice Returns true if currently inside a cross-chain call execution
    /// @return True while an execution entry is being processed.
    function _insideExecution() internal view returns (bool) {
        return _executing;
    }

    /// @notice This L2's own network — `createCrossChainProxy` may not proxy a local address.
    /// @return ROLLUP_ID, the configured identifier of this L2.
    function _getRollupId() internal view override returns (uint64) {
        return ROLLUP_ID;
    }

    /// @notice Copies the `n`-call span at `start` into a fresh memory array. Explicit field copy
    ///         (not element assignment) so the fresh structs don't alias the caller's array. The
    ///         caller zeroes the trigger's `revertNextNCalls` before slicing (so `span[0]` copies 0
    ///         and the isolated re-run won't recurse into the same span).
    /// @param calls Source call array.
    /// @param start Inclusive first index of the span.
    /// @param n Number of calls to copy; the span must fit within calls.
    /// @return span Fresh array of copied call structs sharing the source calldata byte buffers.
    function _sliceCrossChainCalls(
        CrossChainCall[] memory calls,
        uint256 start,
        uint256 n
    )
        internal
        pure
        returns (CrossChainCall[] memory span)
    {
        span = new CrossChainCall[](n);
        for (uint256 k = 0; k < n; k++) {
            CrossChainCall memory source = calls[start + k];
            span[k] = CrossChainCall({
                revertNextNCalls: source.revertNextNCalls,
                isStatic: source.isStatic,
                gas: source.gas,
                sourceAddress: source.sourceAddress,
                sourceRollupId: source.sourceRollupId,
                targetAddress: source.targetAddress,
                value: source.value,
                data: source.data
            });
        }
    }
}

src/base/CrossChainProxy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.34;

import {IEEZ} from "../interfaces/IEEZ.sol";
import {ICrossChainProxy} from "../interfaces/ICrossChainProxy.sol";

/// @title CrossChainProxy
/// @notice Proxy contract for cross-chain addresses, deployed via CREATE2
/// @dev Stores the EEZ manager address as an immutable. Dispatch follows the OZ TransparentProxy
///      pattern, keyed on caller AND selector: `executeOnBehalf` from the EEZ manager forwards
///      directly to the destination, and the `staticCheck()` selector from the proxy itself runs
///      the static-context detector. Every other call, whatever its selector, is routed through
///      the cross-chain execution path via _fallback(). A destination that makes the proxy call
///      itself with the `staticCheck()` selector (via executeOnBehalf) reaches the detector rather
///      than a cross-chain call; this is acceptable.
contract CrossChainProxy {
    // ──────────────────────────────────────────────
    //  Immutables
    // ──────────────────────────────────────────────

    /// @notice The EEZ manager contract address (`EEZ` on L1, `EEZL2` on L2)
    address internal immutable EEZ;

    // ──────────────────────────────────────────────
    //  Transient state
    // ──────────────────────────────────────────────

    /// @dev Dummy transient variable used to detect STATICCALL context.
    ///      Writing to it reverts in a static context; the self-call in _fallback catches this.
    uint256 transient _staticDetector;

    // ──────────────────────────────────────────────
    //  Constants
    // ──────────────────────────────────────────────

    bytes4 private constant STATIC_CHECK_SELECTOR = bytes4(keccak256("staticCheck()"));

    /// @dev Gas cap for the constructor's ether recovery. Bounds what a gas-burning recovery address
    ///      can cost, so deployment still completes after a failed sweep; ample for any plain receiver.
    uint256 private constant RECOVERY_ETHER_GAS = 100_000;

    // ──────────────────────────────────────────────
    //  Constructor
    // ──────────────────────────────────────────────

    /// @notice Stores the deploying EEZ contract as the immutable authorized caller.
    constructor() {
        EEZ = msg.sender;

        // Best-effort sweep of ether sent here before deployment (otherwise stuck —
        // the proxy only forwards msg.value). Ignore transfer failure; ETH then stays here.
        uint256 predeployedEther = address(this).balance;
        if (predeployedEther != 0) {
            // EVM forwards min(RECOVERY_ETHER_GAS, gas available).
            IEEZ(msg.sender).RECOVERY_ADDRESS().call{value: predeployedEther, gas: RECOVERY_ETHER_GAS}("");
        }
    }

    // ──────────────────────────────────────────────
    //  Call dispatch
    // ──────────────────────────────────────────────

    /// @notice Serves `executeOnBehalf` from the EEZ manager and the `staticCheck()` self-probe; every
    ///         other call goes to `_fallback()`, which executes it as a cross-chain call on EEZ.
    /// @dev Check the caller before ABI decoding so selector collisions with malformed arguments
    ///      still reach the remote fallback. Use ICrossChainProxy for the manager forwarding ABI.
    fallback() external payable {
        // Allow executeOnBehalf only when called by the EEZ manager.
        if (msg.sender == EEZ && msg.sig == ICrossChainProxy.executeOnBehalf.selector) {
            (address destination, uint64 callGas, bytes memory data) =
                abi.decode(msg.data[4:], (address, uint64, bytes));

            // Cap gas at the target, leaving proxy overhead outside the cap; zero means uncapped.
            // A manager STATICCALL keeps this CALL and its descendants in static context.
            (bool success, bytes memory result) = callGas == 0
                ? destination.call{value: msg.value}(data)
                : destination.call{value: msg.value, gas: callGas}(data);

            assembly {
                switch success
                case 0 { revert(add(result, 0x20), mload(result)) }
                default { return(add(result, 0x20), mload(result)) }
            }
        }

        // Handle the self-call used to detect static context.
        if (msg.sender == address(this) && msg.sig == STATIC_CHECK_SELECTOR) {
            // TSTORE halts in static context.
            _staticDetector = 0;
            return;
        }

        // Route all other calls through cross-chain execution.
        _fallback();
    }

    // ──────────────────────────────────────────────
    //  Internal helpers
    // ──────────────────────────────────────────────

    /// @dev Internal fallback that forwards the call to the EEZ manager as a cross-chain execution.
    ///      Uses assembly return/revert which terminates the entire call context.
    ///
    ///      Static context detection: a self-call to staticCheck() attempts a transient store.
    ///      If it reverts we're in a STATICCALL — route to staticCrossChainCall (view) instead.
    ///
    ///      Result decoding:
    ///      The low-level `.call()` returns ABI-encoded return data. Since `executeCrossChainCall`
    ///      returns `bytes memory`, the raw `result` is double-encoded: the outer ABI encoding
    ///      wraps the inner `bytes` return value. We must `abi.decode(result, (bytes))` to unwrap
    ///      the inner bytes before returning them to the caller.
    ///      On revert, the raw revert data is not ABI-wrapped, so we forward it directly.
    function _fallback() internal {
        // Detect STATICCALL context: tstore reverts in static context, tload does not.
        // A self-call to staticCheck() isolates the tstore so we can catch the revert.
        // The EEZ contract will be upgradeable, but proxies will not. Read the cap from
        // EEZ on each call so a major EVM gas repricing can be handled by upgrading EEZ
        // to adjust this value, without redeploying proxies or changing their addresses.
        uint256 staticCheckGas = IEEZ(EEZ).STATIC_CHECK_GAS();
        (bool success,) = address(this).call{gas: staticCheckGas}(abi.encodeWithSelector(STATIC_CHECK_SELECTOR));
        bytes memory result;

        if (!success) {
            // Static context — look up pre-computed result via view function
            (success, result) = EEZ.staticcall(abi.encodeCall(IEEZ.staticCrossChainCall, (msg.sender, msg.data)));
        } else {
            // Normal context — execute cross-chain call
            (success, result) =
                EEZ.call{value: msg.value}(abi.encodeCall(IEEZ.executeCrossChainCall, (msg.sender, msg.data)));
        }

        if (success) {
            // Decode the inner `bytes` from the ABI-encoded return value
            result = abi.decode(result, (bytes));
        }

        assembly {
            switch success
            case 0 { revert(add(result, 0x20), mload(result)) }
            default { return(add(result, 0x20), mload(result)) }
        }
    }
}

src/base/EEZBase.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.34;

import {IEEZ, ProxyInfo, RollupUpdate} from "../interfaces/IEEZ.sol";
import {CrossChainProxy} from "./CrossChainProxy.sol";

/// @title EEZBase
/// @notice Direction-neutral shared base for the L1 (`EEZ`) and L2 (`EEZL2`) cross-chain managers.
/// @dev Holds ONLY the machinery that is identical on both sides AND never names a direction-
///      specific execution struct (those structs differ per side — `IEEZ.sol` vs `IEEZL2.sol`):
///        - Rolling-hash tag constants, the `_rollingHash` accumulator, and the fold helpers
///          (they operate on primitives, so they don't reference any execution struct).
///        - The neutral transient pointer `_currentEntryIndex` (which entry the child is executing).
///        - The `authorizedProxies` registry, the external `createCrossChainProxy` entry point,
///          and the internal CREATE2 deploy helper (`_createCrossChainProxyInternal`).
///        - Pure / view helpers (`computeCrossChainCallHash`, `computeCrossChainProxyAddress`).
///        - The `ContextResult` revert transport and its decoder (`_decodeContextResult`).
///        - The set of errors / events that mean the same thing on both contracts and carry no
///          direction in their name.
///
///      What lives in the children (`EEZ` / `EEZL2`) instead, because it names the per-side
///      execution structs or a per-side cursor:
///        - The reentrant-table cursor — `_lastL1ToL2CallConsumed` on L1, `_lastOutgoingCallConsumed`
///          on L2 — and `_insideExecution()` (L1 derives it from its transient allowed-set count, L2 from
///          a dedicated `_executing` flag). The flat-call position is a plain local index in
///          `_processL2ToL1Calls` on L1 / `_processIncomingCalls` on L2 (no transient cursor).
///        - `_processL2ToL1Calls` / `_processIncomingCalls` (active call array by `memory`), `_consumeNestedCall`,
///          `_consumeAndExecute`(`Entry`), the active reentrant-table accessor (L1:
///          `_getExpectedL1toL2Calls`; L2: `_getExpectedOutgoingCalls`), the reentrant resolver
///          (`_resolveNestedReentrant`), `_resolveStaticEntry`,
///          `_processStaticL2ToL1Calls` on L1 / `_processStaticIncomingCalls` on L2,
///          `staticCrossChainCall`, and the force-revert-span slicer (L1: `_sliceL2ToL1Calls`; L2:
///          `_sliceCrossChainCalls`).
///        - The per-side events and errors (L1: `EntryExecuted`, `CallResult`, …;
///          L2: `EntryExecuted`, `CallResult`, …).
abstract contract EEZBase is IEEZ {
    // ──────────────────────────────────────────────
    //  Rolling-hash tag constants
    // ──────────────────────────────────────────────
    uint8 internal constant CALL_BEGIN = 1;
    uint8 internal constant CALL_END = 2;
    uint8 internal constant NESTED_BEGIN = 3;
    uint8 internal constant NESTED_END = 4;
    uint8 internal constant CALL_NOT_FOUND = 5;
    uint8 internal constant CALL_INSUFFICIENT_GAS = 6;

    /// @notice Readable `isStatic` argument for `computeCrossChainCallHash` on non-static (call) paths.
    bool internal constant NOT_STATIC_CALL = false;

    /// @notice Readable `isStatic` argument for `computeCrossChainCallHash` on static (read-only) paths.
    bool internal constant IS_STATIC = true;

    /// @notice `callGas` argument for `computeCrossChainCallHash` when the hash must not depend on gas.
    ///         L1 always passes this constant, so every L1 hash is gas-independent.
    ///         L2 passes it when hashing the incoming calls it executes from the table (the `CALL_BEGIN`
    ///         folds), and in two places passes a real gas value instead: a call leaving the L2 folds
    ///         `gasleft()` when `USE_GAS_LEFT` is set (this constant otherwise), and
    ///         `executeIncomingCrossChainCall` verifies the inbound call with that call's own `gas` field.
    uint64 internal constant ZERO_CALL_GAS = 0;

    /// @notice Gas cap for proxies' static-context probes; read from the EEZ contract on each call.
    /// @dev TSTORE consumes the probe's gas in static context; 1,000 covers the current mutable probe.
    ///      The EEZ contract will be upgradeable, but proxies will not. If a major EVM gas repricing
    ///      occurs, upgrading the EEZ contract can adjust this cap without replacing proxies.
    uint256 public constant STATIC_CHECK_GAS = 1_000;

    /// @dev Estimated dispatch and account-access overhead across EEZ -> proxy -> destination.
    ///      Excludes payload processing and ETH transfers, which are estimated separately.
    uint256 internal constant ESTIMATED_FIXED_CALL_OVERHEAD = 10_000;

    // ──────────────────────────────────────────────
    //  Immutables
    // ──────────────────────────────────────────────

    /// @notice Cached hash of the argument-free proxy creation code for CREATE2 address prediction.
    /// @dev The proxy captures its deploying EEZ contract via msg.sender, so this hash is also
    ///      valid when EEZ runs through delegatecall. CREATE2 binds the deployer address separately.
    bytes32 public immutable PROXY_INIT_CODE_HASH;

    // ──────────────────────────────────────────────
    //  Storage shared with children
    // ──────────────────────────────────────────────

    /// @notice Mapping of authorized CrossChainProxy contracts to their identity
    mapping(address proxy => ProxyInfo info) public authorizedProxies;

    // ──────────────────────────────────────────────
    //  Transient execution state shared with children
    // ──────────────────────────────────────────────

    /// @notice Transient rolling hash accumulating tagged events across the entire entry
    bytes32 transient _rollingHash;

    /// @notice The current execution entry being processed.
    /// @dev L1 uses this to index `_transientEntries` while a batch is mid-flight, otherwise
    ///      `verificationByRollup[_currentEntryRollupId].entryQueue`. L2 always indexes `entries`.
    ///      Both meanings are consistent — the child decides where the cursor points.
    uint256 transient _currentEntryIndex;

    // ──────────────────────────────────────────────
    //  Events
    // ──────────────────────────────────────────────

    /// @notice Emitted when a new CrossChainProxy is deployed and registered
    event CrossChainProxyCreated(
        address indexed proxy, address indexed originalAddress, uint64 indexed originalRollupId
    );

    /// @notice Emitted when a cross-chain call is executed via proxy
    event CrossChainCallExecuted(
        bytes32 indexed crossChainCallHash, address indexed proxy, address sourceAddress, bytes callData, uint256 value
    );

    // ──────────────────────────────────────────────
    //  Errors
    // ──────────────────────────────────────────────

    /// @notice Error when caller is not a registered CrossChainProxy
    error UnauthorizedProxy();

    /// @notice Error when a self-call-only entry point (`executeInContextAndRevert`,
    ///         L1's `_attemptExecuteImmediateL2Txs`) is called by an external address
    error NotSelf();

    /// @notice Error when no matching execution entry exists for the call hash
    error ExecutionNotFound();

    /// @notice Error when the computed rolling hash doesn't match the entry's `rollingHash`
    error RollingHashMismatch();

    /// @notice Error when an entry begins while `_rollingHash` is still non-zero — a prior
    ///         entry left the accumulator un-reset (it must be cleared between entries)
    error RollingHashNotCleared();

    /// @notice Carries execution results out of a reverted context
    /// @dev Direction-neutral transport. A no-match folds CALL_NOT_FOUND into `_rollingHash`, which
    ///      is carried in the first field, so the isolated frame's not-found survives the revert with
    ///      no separate flag.
    error ContextResult(bytes32 rollingHash, uint256 reentrantConsumed);

    /// @notice Error when `executeInContextAndRevert` reverts with an unexpected error
    error UnexpectedContextRevert(bytes revertData);

    /// @notice A forwarded cross-chain call cannot target this EEZ manager.
    error EEZDestinationForbidden();

    /// @notice Error when a static sub-call targets an un-deployed proxy
    /// @dev STATICCALL to a codeless address returns `(true, "")`; prover could pre-hash that.
    error StaticCallProxyNotDeployed(address sourceProxy);

    /// @notice Error when a call marked `isStatic` was loaded carrying ETH value.
    /// @dev A STATICCALL cannot transfer value, so a non-zero `value` on a static call is a
    ///      malformed entry. We reject it explicitly rather than silently dropping the value.
    error StaticCallWithValue();

    /// @notice A static sub-call cannot be dispatched with its declared gas cap.
    error InsufficientCallGas(uint64 callGas);

    /// @notice Error when a sub-call of a static resolution is not marked `isStatic`.
    /// @dev Those calls run via STATICCALL whatever the flag says, and the untagged static rolling
    ///      hash folds only `(success, retData)` — so an unchecked `false` would let a proven
    ///      state-changing call execute read-only undetected.
    error NonStaticSubCall();

    /// @notice Error when a static-resolution sub-call carries a `revertNextNCalls` span — there is
    ///         no state to roll back. Defensive check of a prover constraint.
    error StaticCallWithRevertSpan();

    /// @notice Error when a SUCCESS row of the unified reentrant table carries a non-zero
    ///         `revertedOrStaticRollingHash` — the field is only read on the STATIC / REVERTED
    ///         paths. Defensive check of a prover constraint.
    error SuccessRowWithRevertedOrStaticHash();

    /// @notice Error when a proxy is requested for an address on THIS manager's own network.
    /// @dev A CrossChainProxy stands in for a REMOTE address; a same-network proxy is meaningless
    ///      and unsafe. L1 (EEZ) forbids `MAINNET_ROLLUP_ID` (0); L2 (EEZL2) forbids its own
    ///      `ROLLUP_ID`. Enforced in `_createCrossChainProxyInternal`, so every creation path
    ///      (`createCrossChainProxy`, `getOrCreateCrossChainProxy`, execution) is covered.
    error SameNetworkProxy(uint64 rollupId);

    // ──────────────────────────────────────────────
    //  Constructor
    // ──────────────────────────────────────────────

    /// @notice Caches the proxy creation-code hash used to compute deterministic proxy addresses.
    constructor() {
        // Every proxy is deployed with the same creation code
        PROXY_INIT_CODE_HASH = keccak256(type(CrossChainProxy).creationCode);
    }

    // ──────────────────────────────────────────────
    //  Proxy creation
    // ──────────────────────────────────────────────

    /// @notice This manager's own network rollup id — a proxy may NOT be created for it.
    /// @dev L1 (EEZ) returns `MAINNET_ROLLUP_ID` (0); L2 (EEZL2) returns its own `ROLLUP_ID`.
    /// @return Identifier of this manager's own network, which cannot be a proxy's remote network.
    function _getRollupId() internal view virtual returns (uint64);

    /// @notice Creates a new CrossChainProxy for an address on another rollup
    /// @param originalAddress The address this proxy represents on the source rollup
    /// @param originalRollupId The source rollup ID
    /// @return proxy The deployed proxy address
    function createCrossChainProxy(address originalAddress, uint64 originalRollupId) external returns (address proxy) {
        return _createCrossChainProxyInternal(originalAddress, originalRollupId);
    }

    /// @notice Returns the authorized proxy for a remote address, deploying it if needed.
    /// @dev A same-network proxy can never be authorized, so that case always reaches the
    ///      deploy helper and reverts `SameNetworkProxy` there.
    /// @param originalAddress The address this proxy represents on the source rollup
    /// @param originalRollupId The source rollup ID
    /// @return proxy The existing or newly deployed proxy address
    function getOrCreateCrossChainProxy(
        address originalAddress,
        uint64 originalRollupId
    )
        public
        returns (address proxy)
    {
        proxy = computeCrossChainProxyAddress(originalAddress, originalRollupId);
        if (!authorizedProxies[proxy].isProxy) {
            proxy = _createCrossChainProxyInternal(originalAddress, originalRollupId);
        }
    }

    /// @notice Deploys a CrossChainProxy via CREATE2 and registers it as authorized
    /// @param originalAddress Remote address represented by the new proxy.
    /// @param originalRollupId Remote rollup ID; must differ from this manager's own network.
    /// @return proxy Newly deployed and authorized proxy address.
    function _createCrossChainProxyInternal(
        address originalAddress,
        uint64 originalRollupId
    )
        internal
        returns (address proxy)
    {
        // A proxy stands in for a REMOTE address — never one on this manager's own network.
        if (originalRollupId == _getRollupId()) revert SameNetworkProxy(originalRollupId);
        bytes32 salt = keccak256(abi.encodePacked(originalRollupId, originalAddress));
        proxy = address(new CrossChainProxy{salt: salt}());
        authorizedProxies[proxy] = ProxyInfo(true, originalAddress, originalRollupId);
        emit CrossChainProxyCreated(proxy, originalAddress, originalRollupId);
    }

    /// @notice Computes the deterministic CREATE2 address for a CrossChainProxy
    /// @param originalAddress The address this proxy represents on the source rollup
    /// @param originalRollupId The source rollup ID
    /// @return Predicted proxy address, whether or not the proxy has been deployed.
    function computeCrossChainProxyAddress(
        address originalAddress,
        uint64 originalRollupId
    )
        public
        view
        returns (address)
    {
        bytes32 salt = keccak256(abi.encodePacked(originalRollupId, originalAddress));
        return
            address(
                uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), address(this), salt, PROXY_INIT_CODE_HASH))))
            );
    }

    // ──────────────────────────────────────────────
    //  Cross-chain call hash helper
    // ──────────────────────────────────────────────

    /// @notice Computes the cross-chain call hash from individual fields. Public so off-chain
    ///         tooling can derive the hash for a planned cross-chain call.
    /// @dev Ordered isStatic → FROM (source pair) → TO (target pair) → value → callGas → data;
    ///      reordering would break every on-chain hash check and every off-chain tool that
    ///      pre-computes the hash. `isStatic` makes a read-only call hash distinctly from an
    ///      otherwise-identical state-changing one. `callGas` is 0 except for calls leaving an L2
    ///      with `USE_GAS_LEFT`, where it is the gas left when the L2 manager computes this hash.
    /// @param isStatic Whether the cross-chain call is read-only.
    /// @param sourceAddress Original caller address on the source rollup.
    /// @param sourceRollupId Identifier of the source rollup.
    /// @param targetAddress Destination address on the target rollup.
    /// @param targetRollupId Identifier of the target rollup.
    /// @param value Ether value bound to the call.
    /// @param callGas Gas field committed into the call identity according to the calling path's gas policy.
    /// @param data Calldata bound to the call.
    /// @return Keccak256 hash of the ABI-encoded call fields in protocol order.
    function computeCrossChainCallHash(
        bool isStatic,
        address sourceAddress,
        uint64 sourceRollupId,
        address targetAddress,
        uint64 targetRollupId,
        uint256 value,
        uint64 callGas,
        bytes memory data
    )
        public
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(isStatic, sourceAddress, sourceRollupId, targetAddress, targetRollupId, value, callGas, data)
        );
    }

    // ──────────────────────────────────────────────
    //  Revert-context decode helper
    // ──────────────────────────────────────────────

    /// @notice Decodes a `ContextResult` revert payload returned by `executeInContextAndRevert`.
    /// @dev Validates selector AND length (4 + 2*32 = 68) before the raw mloads — defense
    ///      against a truncated revert that happens to share the selector.
    /// @param revertData Raw revert payload expected to encode ContextResult.
    /// @return rollingHash Accumulator value reported by the reverted execution context.
    /// @return reentrantConsumed Reentrant-table cursor reported by the reverted execution context.
    function _decodeContextResult(bytes memory revertData)
        internal
        pure
        returns (bytes32 rollingHash, uint256 reentrantConsumed)
    {
        if (bytes4(revertData) != ContextResult.selector) {
            revert UnexpectedContextRevert(revertData);
        }
        if (revertData.length < 68) revert UnexpectedContextRevert(revertData);
        assembly {
            let ptr := add(revertData, 36)
            rollingHash := mload(ptr)
            reentrantConsumed := mload(add(ptr, 32))
        }
    }

    /// @notice Content-addressed position key for a row of the unified reentrant table (L1's
    ///         `expectedL1toL2Hash`, L2's `expectedOutgoingHash` — same formula): the call's
    ///         identity hash (which already folds `isStatic` and the routed rollup) bound to the
    ///         live `_rollingHash` at the instant it fires. One comparison replaces the old
    ///         (hash, rollingHash, isStatic) triple.
    /// @param crossChainCallHash Identity hash of the reentrant cross-chain call.
    /// @param rollingHash Execution accumulator at the point the call is made.
    /// @return Lookup key binding the call identity to its execution position.
    function _computeExpectedL1toL2Hash(
        bytes32 crossChainCallHash,
        bytes32 rollingHash
    )
        internal
        pure
        returns (bytes32)
    {
        return keccak256(abi.encodePacked(crossChainCallHash, rollingHash));
    }

    // ──────────────────────────────────────────────
    //  Rolling hash helpers
    // ──────────────────────────────────────────────
    //
    // The entry-level `_rollingHash` accumulator is updated at six event points during
    // entry execution: at the start and end of each executed call, at the start and end of
    // each reentrant frame, when a reentrant call finds no matching row, and when a capped
    // call lacks dispatch gas. Each event has a distinct domain-byte tag,
    // so the same set of inputs can't collide across event types. The final value is checked
    // against `entry.rollingHash` at the end of execution.
    //
    // Valid proofs must exclude CALL_INSUFFICIENT_GAS and CALL_NOT_FOUND;
    // surviving failure markers make a valid expected rolling-hash check fail. Ordinary
    // enclosing reverts erase them; ContextResult transports them across deliberate spans.
    // Hash equality alone cannot enforce this external proof-policy requirement.
    //
    // No call/frame INDEX is folded in: `_rollingHash` is a chain (each fold depends on the
    // prior value), so order, count, and nesting are already bound by the chain + the tags. An
    // explicit index would be a deterministic `1,2,3,…` that adds no information — omitting it is
    // what lets a `revertNextNCalls` span be processed as a 0-based sub-slice without diverging
    // the hash from a continuous run.
    //
    // Static-call sub-hashes (`_rollingHashStaticResult`) use a simpler, untagged formula
    // because they're verified against `StaticExecutionEntry.rollingHash`, a separate accumulator
    // whose surrounding static-entry key already pins the entry/call/nesting context.
    //
    // These tags are protocol constants — a call executed on either chain MUST hash the same
    // way for the proof, so the "nested" wording here is the neutral rolling-hash frame
    // concept, NOT a direction (the directional naming lives in the per-side children).

    /// @notice Initializes `_rollingHash` to an entry's BEGIN seed — the ordered
    ///         `(rollupId, currentRoot)` state context closed with the entry's identity
    ///         (`proxyEntryHash` == its crossChainCallHash) — so the hash binds the entry's STARTING
    ///         STATE + identity, not just call results (nested frames inherit it transitively).
    /// @dev The one rolling-hash helper that names a per-side struct (L1 `RollupUpdate`); L2 has no
    ///      rollup updates, so it seeds with its own `EEZL2._seedRollingHash` — the same formula with
    ///      an empty update prefix. Updates are strictly-increasing-by-rollupId, so the fold is
    ///      deterministic.
    ///   seed         = keccak(…keccak(0, rollupId_1, currentRoot_1)…, rollupId_n, currentRoot_n)
    ///   _rollingHash = keccak(seed, proxyEntryHash)
    /// @param rollupUpdates Ordered rollup IDs and starting roots to bind into the seed.
    /// @param proxyEntryHash Inbound call identity, or zero for a pure-L2 transaction entry.
    function _rollingHashEntryBegin(RollupUpdate[] memory rollupUpdates, bytes32 proxyEntryHash) internal {
        if (_rollingHash != bytes32(0)) revert RollingHashNotCleared();

        bytes32 _rollupRootsHash;
        for (uint256 i = 0; i < rollupUpdates.length; i++) {
            _rollupRootsHash =
                keccak256(abi.encodePacked(_rollupRootsHash, rollupUpdates[i].rollupId, rollupUpdates[i].currentRoot));
        }
        _rollingHash = keccak256(abi.encodePacked(_rollupRootsHash, proxyEntryHash));
    }

    /// @notice Rejects calls that would re-enter this manager with a proxy's authorized identity.
    /// @param destination Local destination of the forwarded cross-chain call.
    function _validateCallDestination(address destination) internal view {
        if (destination == address(this)) revert EEZDestinationForbidden();
    }

    /// @notice Checks the estimated gas budget to protect users from composer underfunding,
    ///         whether accidental or deliberate, being mistaken for a destination call failure.
    /// @dev callGas == 0 skips the check and forwards available gas, subject to EVM forwarding limits.
    ///      Check after encoding the payload and resolving the proxy. Account-creation gas is
    ///      the poster's responsibility and, along with normal EVM rules, may reduce the gas delivered
    ///      to the destination below callGas. This estimate excludes return-data processing and the rest of the entry.
    /// @param callGas Requested destination gas cap; zero bypasses the budget check.
    /// @param payloadLength Byte length of the already-encoded proxy forwarding payload.
    /// @param value Ether value forwarded, used to estimate transfer overhead.
    /// @return True if the cap is zero or gasleft() meets the estimated dispatch budget.
    function _hasEnoughCallGas(uint64 callGas, uint256 payloadLength, uint256 value) internal view returns (bool) {
        if (callGas == 0) return true;
        // Arithmetic is bounded by the uint64 cap and the allocated payload's EVM memory limits.
        unchecked {
            // Extra words allow for rounding, headers and scratch space in the proxy.
            uint256 words = payloadLength / 32 + 8;
            // Proxy copying: 3 gas/word; memory expansion: 3 gas/word + words²/512.
            // EEZ encoded the payload before this check, so its encoding cost is already paid.
            uint256 payloadCost = 6 * words + words * words / 512;
            // Fixed overhead plus two 9,000-gas transfers when sending ETH.
            uint256 budget = uint256(callGas) + ESTIMATED_FIXED_CALL_OVERHEAD + payloadCost + (value == 0 ? 0 : 18_000);
            // Approximate both EIP-150 margins with 64/62, rounded up.
            uint256 required = (budget * 64 + 61) / 62;
            return gasleft() >= required;
        }
    }

    /// @notice Folds a CALL_BEGIN event into `_rollingHash`, binding the call's IDENTITY
    ///         (`crossChainCallHash`) so the hash commits to which call ran, not just its result.
    /// @param crossChainCallHash Identity hash of the call whose execution is beginning.
    function _rollingHashCallBegin(bytes32 crossChainCallHash) internal {
        _rollingHash = keccak256(abi.encodePacked(_rollingHash, CALL_BEGIN, crossChainCallHash));
    }

    /// @notice Folds a CALL_END event into `_rollingHash`, including the call's observed
    ///         outcome (success flag + raw return/revert data).
    /// @param success Whether the executed call succeeded.
    /// @param retData Raw return data on success or revert data on failure.
    function _rollingHashCallEnd(bool success, bytes memory retData) internal {
        _rollingHash = keccak256(abi.encodePacked(_rollingHash, CALL_END, success, retData));
    }

    /// @notice Folds a NESTED_BEGIN event into `_rollingHash` (start of a reentrant frame), binding
    ///         the reentrant call's IDENTITY (`crossChainCallHash`).
    /// @param crossChainCallHash Identity hash of the reentrant call opening the nested frame.
    function _rollingHashNestedBegin(bytes32 crossChainCallHash) internal {
        _rollingHash = keccak256(abi.encodePacked(_rollingHash, NESTED_BEGIN, crossChainCallHash));
    }

    /// @notice Folds a NESTED_END event into `_rollingHash` (end of a reentrant frame).
    function _rollingHashNestedEnd() internal {
        _rollingHash = keccak256(abi.encodePacked(_rollingHash, NESTED_END));
    }

    /// @notice Appends CALL_NOT_FOUND (5) when a reentrant call has no matching expected entry.
    /// @dev Distinct from a normal empty return. Valid proofs must exclude this marker,
    ///      so the hash mismatch reverts the enclosing execution at validation.
    ///      Ordinary reverts erase it; ContextResult preserves it across deliberate rollback spans.
    /// @param crossChainCallHash Identity hash of the reentrant call with no matching expected row.
    function _rollingHashCallNotFound(bytes32 crossChainCallHash) internal {
        _rollingHash = keccak256(abi.encodePacked(_rollingHash, CALL_NOT_FOUND, crossChainCallHash));
    }

    /// @notice Appends CALL_INSUFFICIENT_GAS (6) when a call lacks gas and its local call array stops.
    /// @dev CALL_BEGIN already identifies the call. Valid proofs must exclude this marker,
    ///      so the hash mismatch reverts the enclosing execution at validation.
    ///      Ordinary reverts erase it; ContextResult preserves it across deliberate rollback spans.
    function _rollingHashCallInsufficientGas() internal {
        _rollingHash = keccak256(abi.encodePacked(_rollingHash, CALL_INSUFFICIENT_GAS));
    }

    /// @notice Folds a static sub-call result into a local accumulator. Pure: doesn't touch
    ///         `_rollingHash` because static sub-calls are verified against
    ///         `StaticExecutionEntry.rollingHash`, a separate per-static-entry accumulator.
    /// @dev The schema is untagged — the surrounding static-entry key already pins the
    ///      entry/call context that the tagged events disambiguate at entry level.
    /// @param prev Accumulator before this sub-call, or zero for the first result.
    /// @param success Whether the static sub-call succeeded.
    /// @param retData Raw return data on success or revert data on failure.
    /// @return Updated static-result accumulator.
    function _rollingHashStaticResult(bytes32 prev, bool success, bytes memory retData)
        internal
        pure
        returns (bytes32)
    {
        return keccak256(abi.encodePacked(prev, success, retData));
    }
}

